"use strict";(globalThis.webpackChunk_8x8_developer_docs=globalThis.webpackChunk_8x8_developer_docs||[]).push([[37375],{64198:e=>{e.exports=JSON.parse('{"id":"2026-09-23-whatsapp-business-calling-guides-rewritten","date":"2026-09-23","products":["Connect"],"product":"Connect","channel":"WhatsApp","changeType":"Changed","title":"WhatsApp Business Calling guides rewritten","excerpt":"The four WhatsApp Business Calling guides (overview, user-initiated, business-initiated, and scenarios) have been rewritten to match how calling is delivered on 8x8.","hasArticle":true,"bodyHtml":"<p>The four WhatsApp Business Calling guides (overview, user-initiated, business-initiated, and scenarios) have been rewritten to match how calling is delivered on 8x8.</p>\\n<h2>What changed</h2>\\n<ul>\\n<li><p><strong>Topology:</strong> calls are SIP end to end. Meta connects to 8x8 over SIP, and 8x8 connects to your SBC, PBX, or contact center over SIP. There&#39;s no REST API for placing a call. REST APIs on <code>chatapps.8x8.com</code> are used only for permissions and templates, and only on the Direct SIP path for business-initiated calls.</p>\\n</li>\\n<li><p><strong>Four integration paths</strong>, all set up with your 8x8 account manager:</p>\\n<table>\\n<thead>\\n<tr>\\n<th>Path</th>\\n<th>Calling today</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td>Direct SIP</td>\\n<td>User-initiated and business-initiated</td>\\n</tr>\\n<tr>\\n<td>8x8 Converse</td>\\n<td>User-initiated and business-initiated (Converse handles templates and permissions)</td>\\n</tr>\\n<tr>\\n<td>Genesys</td>\\n<td>User-initiated only</td>\\n</tr>\\n<tr>\\n<td>VCC via AI Studio</td>\\n<td>User-initiated only</td>\\n</tr>\\n</tbody></table>\\n</li>\\n<li><p><strong>Business-initiated calling</strong> is now a 5-step Direct SIP walkthrough: create the <code>CALL_PERMISSION_REQUEST</code> template, send it, receive <code>callPermissionReply</code> on the inbound-message webhook, check <code>callPermissions</code> before every call, then place the call from your SIP endpoint.</p>\\n</li>\\n<li><p><strong>Permission model:</strong> the user chooses a temporary permission (7 days) or a permanent one (no expiry). Rate limits, auto-revocation after 4 consecutive unanswered calls, and error <code>138017</code> are documented. No webhook is sent when a temporary permission expires.</p>\\n</li>\\n<li><p><strong>User-initiated calling</strong> adds the <code>VOICE_CALL</code> template button, <code>wa.me/call/</code> deep links, and <code>cta_payload</code> attribution.</p>\\n</li>\\n<li><p><strong>Prerequisites:</strong> WhatsApp Messaging must be active first, plus Meta business verification, a messaging tier of at least 2,000 unique recipients per day, and a credit line on the WABA for business-initiated calls.</p>\\n</li>\\n<li><p><strong>New sections</strong> on pricing (6-second pulses for business-initiated calls; user-initiated calls are free), operational limits (1,000 concurrent calls per number; OPUS, PCMA, and PCMU codecs), and reporting (Converse reporting, Voice Session Summary, call recording).</p>\\n</li>\\n</ul>\\n<h2>Read more</h2>\\n<ul>\\n<li><a href=\\"/connect/docs/voice/whatsapp-business-calling/overview\\">WhatsApp Business Calling overview</a></li>\\n<li><a href=\\"/connect/docs/voice/whatsapp-business-calling/business-initiated\\">Business-initiated calling</a></li>\\n<li><a href=\\"/connect/docs/voice/whatsapp-business-calling/user-initiated\\">User-initiated calling</a></li>\\n<li><a href=\\"/connect/docs/voice/whatsapp-business-calling/scenarios\\">Supported calling scenarios</a></li>\\n</ul>\\n"}')}}]);